const body = $json.body ?? $json;
const command = String(body.command ?? body.message ?? '').trim();
const upper = command.toUpperCase();
let team = 'CEO';
if (upper.startsWith('MEDIA:') || /YOUTUBE|TIKTOK|INSTAGRAM|SPOTIFY|SUNO|VIDEO|MÜZİK/.test(upper)) team = 'MEDIA';
else if (upper.startsWith('COMMERCE:') || /SHOPIFY|ÜRÜN|DROPSHIPPING|REKLAM|MARJ/.test(upper)) team = 'COMMERCE';
else if (upper.startsWith('NWASB:') || /FATURA|TEKLİF|ARAÇ|MÜŞTERİ|PARÇA|SERVİS/.test(upper)) team = 'NWASB';
else if (upper.startsWith('DEV:') || /GITHUB|N8N|SUPABASE|VERCEL|API|KOD|YAZILIM/.test(upper)) team = 'DEV';
return [{ json: { ok: true, team, command, status: 'ROUTED', requiresHumanApproval: false, createdAt: new Date().toISOString() } }];
